excels.excel:

EXPORT WITH SHEET="产品毛利贡献分析表", HEADER=true,
    MAPPING={"a":"产品名称","b":"销售额","c":"成本","d":"毛利","e":"毛利率","f":"贡献占比"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%","f":"0.00%"},
    FORMULAS={
        D2:'B2-C2',E2:'D2/B2',F2:'D2/D7',
        D3:'B3-C3',E3:'D3/B3',F3:'D3/D7',
        D4:'B4-C4',E4:'D4/B4',F4:'D4/D7',
        D5:'B5-C5',E5:'D5/B5',F5:'D5/D7',
        D6:'B6-C6',E6:'D6/B6',F6:'D6/D7',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'B7-C7',E7:'D7/B7',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
